def _handle_exception(exc: Exception) -> tuple[int, dict[str, Any]]:
    if isinstance(exc, ApiError):
        return _error_payload(exc.message, status_code=exc.status_code, error_type="request_error")
    if isinstance(exc, UserNotEnrolledError):
        return _error_payload(str(exc), status_code=404, error_type="not_found")
    if isinstance(exc, (DependencyUnavailableError, AugmentationDependencyUnavailableError)):
        return _error_payload(str(exc), status_code=503, error_type="dependency_error")
    if isinstance(exc, (SpeakerEngineError, AugmentationError, ValueError)):
        return _error_payload(str(exc), status_code=400, error_type="processing_error")
    return _error_payload(str(exc), status_code=500, error_type="internal_error")

