def read_iceberg_plate(metadata_path: Path) -> dict[str, Any]:
    """Read all plate fields from the current snapshot in Iceberg metadata."""
    metadata = json.loads(metadata_path.read_text())
    snapshot_id = int(metadata["current-snapshot-id"])
    snapshot = next(
        candidate for candidate in metadata["snapshots"] if int(candidate["snapshot-id"]) == snapshot_id
    )
    summary = snapshot["summary"]
    return {
        "snapshotId": snapshot_id,
        "committedAt": _utc_iso_from_millis(int(snapshot["timestamp-ms"])),
        "schemaVersion": int(metadata["format-version"]),
        "rowCount": int(summary["total-records"]),
