def run_profiled_query(
    con: duckdb.DuckDBPyConnection,
    sql: str,
    profile_path: Path,
    built_at: str,
) -> dict[str, Any]:
    """Execute one query and source telemetry from DuckDB's JSON profiler."""
    profile_path.unlink(missing_ok=True)
    profile_sql_path = str(profile_path).replace("'", "''")
    con.execute("PRAGMA enable_profiling='json'")
    con.execute(f"PRAGMA profiling_output='{profile_sql_path}'")
    cursor = con.execute(sql)
    columns = [column[0] for column in cursor.description]
    values = cursor.fetchall()
    con.execute("PRAGMA disable_profiling")
    profile = json.loads(profile_path.read_text())
    rows = [
        {column: _json_scalar(value) for column, value in zip(columns, row, strict=True)}
        for row in values
    ]
    if len(rows) > 20:
        raise RuntimeError(f"curated query returned {len(rows)} rows; maximum is 20")
    return {
        "rows": rows,
        "telemetry": {
            "rowsScanned": int(profile["cumulative_rows_scanned"]),
            "elapsedMs": round(float(profile["latency"]) * 1000, 3),
            "bytesScanned": int(profile["total_bytes_read"]),
        },
        "builtAt": built_at,
    }


