            {workspace === "image" ? <PrivacyImageLab locale={locale} sampleTrigger={imageSampleTrigger} /> : null}
            {workspace === "pdf" ? <PrivacyPdfLab locale={locale} sampleTrigger={pdfSampleTrigger} /> : null}

