                aria-selected={workspace === id}
                className={`privacy-action-link${workspace === id ? " current" : ""}`}
                onClick={() => onSwitch(id)}
              >
                {WORKSPACE_WORD[id]}
              </button>
            </span>
          ))}
        </span>
      ),
    },
  ];
}

